-- interview-batch5-diagrams.sql — 面試題庫補圖 批次 5（bank 最後 6 題）
-- q18  tr = 0.8473 x Rp x Cb 的直線圖：2.2k -> 186ns PASS、10k -> 847ns FAIL
-- q20  ESD 模型 HBM vs CDM 五項對照（含 HBM 峰值 2kV/1.5k = 1.33A）
-- q21  去耦電容擺位：rail -> 10uF -> 100nF -> pin，三個接地 via
-- q23  差分對走線 對 vs 錯（正確側等長等距實測 skew = 0）
-- q24  MOSFET 六參數 + 兩條等 FOM 曲線
-- q25  Latch-up 寄生 PNPN 等效電路（含交叉耦合與紅色低阻抗路徑）
--
-- 驗證：瀏覽器重疊實測 = 0；語意/幾何斷言全過。
-- 其中 q18 的斷言抓到真 bug：tr 公式單位少除 1000（kohm x pF 已經是 ns），
--   修正前曲線與標點全部跑到畫布外，重疊檢查卻是乾淨的 — 只驗重疊不夠。
-- 用法：Supabase Dashboard → SQL Editor → 全部貼上 → Run。冪等，可重跑。

-- q18：tr-Rp 關係：為什麼加大 Rp 是錯的
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="252" viewBox="0 0 520 252" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="252" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Why raising Rp is the wrong fix for a tr failure</text><line x1="70" y1="50" x2="70" y2="190" stroke="#888" stroke-width="1.4"/><line x1="70" y1="190" x2="470" y2="190" stroke="#888" stroke-width="1.4"/><polyline points="70,190 424.1,50.0" fill="none" stroke="#00d4ff" stroke-width="2"/><polyline points="70,190 247.0,50.0" fill="none" stroke="#888" stroke-width="1.6" stroke-dasharray="4"/><line x1="70" y1="143.3" x2="470" y2="143.3" stroke="#ff6b6b" stroke-width="1.2" stroke-dasharray="3"/><text x="466" y="136" fill="#ff6b6b" font-size="11" text-anchor="end">300ns limit (Fast mode)</text><circle cx="143.3" cy="161.0" r="4" fill="#00ff88"/><text x="150" y="178" fill="#00ff88" font-size="11">Rp 2.2k -&gt; tr 186ns  PASS</text><circle cx="403.3" cy="58.2" r="4" fill="#ff6b6b"/><text x="398" y="48" fill="#ff6b6b" font-size="11" text-anchor="end">Rp 10k -&gt; tr 847ns  FAIL</text><text x="66" y="46" fill="#888" font-size="11" text-anchor="end">tr</text><text x="474" y="186" fill="#888" font-size="11">Rp</text><text x="10" y="208" fill="#00ff88" font-size="11">(A) lower Rp: OK    (B) shorter trace = lower Cb: OK    (D) fewer slaves: OK</text><text x="10" y="228" fill="#ff6b6b" font-size="11">(C) raise Rp 2.2k -&gt; 10k: WRONG - tr grows with Rp, the failure gets worse.</text><text x="10" y="246" fill="#888" font-size="11">Solid line Cb = 100pF, dashed Cb = 200pF. tr = 0.8473 x Rp x Cb.</text></svg></div>$vsq$ as box) n
 where question like $q$%tr (上升時間) FAIL%$q$;

-- q20：HBM vs CDM 五項對照
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="240" viewBox="0 0 520 240" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="240" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">ESD models: HBM vs CDM</text><text x="250" y="52" fill="#ffc107" font-size="12" font-weight="bold" text-anchor="middle">HBM</text><text x="410" y="52" fill="#ff6b6b" font-size="12" font-weight="bold" text-anchor="middle">CDM</text><line x1="20" y1="60" x2="500" y2="60" stroke="#888" stroke-width="1.4"/><line x1="176" y1="38" x2="176" y2="182" stroke="#334155" stroke-width="1.2"/><line x1="330" y1="38" x2="330" y2="182" stroke="#334155" stroke-width="1.2"/><text x="24" y="82" fill="#c8d4ee" font-size="11">models</text><text x="253" y="82" fill="#ffc107" font-size="11" text-anchor="middle">a human touching the IC</text><text x="415" y="82" fill="#ff6b6b" font-size="11" text-anchor="middle">the IC itself is charged</text><text x="24" y="104" fill="#c8d4ee" font-size="11">circuit</text><text x="253" y="104" fill="#ffc107" font-size="11" text-anchor="middle">100pF + 1.5k</text><text x="415" y="104" fill="#ff6b6b" font-size="11" text-anchor="middle">package C 1-30pF, ~1 ohm</text><text x="24" y="126" fill="#c8d4ee" font-size="11">duration</text><text x="253" y="126" fill="#ffc107" font-size="11" text-anchor="middle">~150ns</text><text x="415" y="126" fill="#ff6b6b" font-size="11" text-anchor="middle">~1ns (very fast)</text><text x="24" y="148" fill="#c8d4ee" font-size="11">typ level</text><text x="253" y="148" fill="#ffc107" font-size="11" text-anchor="middle">2kV (Class 2)</text><text x="415" y="148" fill="#ff6b6b" font-size="11" text-anchor="middle">500V (Class C4)</text><text x="24" y="170" fill="#c8d4ee" font-size="11">damage</text><text x="253" y="170" fill="#ffc107" font-size="11" text-anchor="middle">junction burn-out</text><text x="415" y="170" fill="#ff6b6b" font-size="11" text-anchor="middle">oxide breakdown</text><text x="10" y="206" fill="#c8d4ee" font-size="11">Peak: HBM = 2kV / 1.5k = 1.33A over ~150ns. CDM dumps several A within ~1ns.</text><text x="10" y="226" fill="#888" font-size="11">Protect: TVS at the connector, guard ring, clamp to VDD/GND rails, keep traces short.</text></svg></div>$vsq$ as box) n
 where question like $q$%什麼是 ESD%$q$;

-- q21：去耦電容擺位與 via
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="244" viewBox="0 0 520 244" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="244" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Decoupling placement: rail -&gt; cap -&gt; pin</text><line x1="40" y1="90" x2="340" y2="90" stroke="#ff6b6b" stroke-width="2"/><text x="14" y="86" fill="#ff6b6b" font-size="11">VDD</text><line x1="140" y1="90" x2="140" y2="104" stroke="#888" stroke-width="1.4"/><line x1="130" y1="104" x2="150" y2="104" stroke="#ffc107" stroke-width="2"/><line x1="130" y1="112" x2="150" y2="112" stroke="#ffc107" stroke-width="2"/><line x1="140" y1="112" x2="140" y2="150" stroke="#888" stroke-width="1.4"/><circle cx="140" cy="150" r="3.5" fill="#00ff88"/><text x="140" y="72" fill="#ffc107" font-size="11" text-anchor="middle">10uF</text><line x1="270" y1="90" x2="270" y2="104" stroke="#888" stroke-width="1.4"/><line x1="260" y1="104" x2="280" y2="104" stroke="#ffc107" stroke-width="2"/><line x1="260" y1="112" x2="280" y2="112" stroke="#ffc107" stroke-width="2"/><line x1="270" y1="112" x2="270" y2="150" stroke="#888" stroke-width="1.4"/><circle cx="270" cy="150" r="3.5" fill="#00ff88"/><text x="270" y="72" fill="#ffc107" font-size="11" text-anchor="middle">100nF</text><rect x="340" y="54" width="120" height="80" rx="4" fill="none" stroke="#00d4ff" stroke-width="1.8"/><text x="400" y="98" fill="#00d4ff" font-size="12" text-anchor="middle" font-weight="bold">IC</text><line x1="400" y1="134" x2="400" y2="150" stroke="#888" stroke-width="1.4"/><circle cx="400" cy="150" r="3.5" fill="#00ff88"/><line x1="40" y1="150" x2="470" y2="150" stroke="#4b5563" stroke-width="4"/><text x="40" y="170" fill="#888" font-size="11">GND plane (vias short and fat = low ESL)</text><text x="10" y="196" fill="#c8d4ee" font-size="11">Order matters: rail -&gt; 10uF -&gt; 100nF -&gt; IC pin. No T-stub hanging off the rail.</text><text x="10" y="216" fill="#c8d4ee" font-size="11">100nF nearest the pin, 10uF further out. One cap per supply pin.</text><text x="10" y="236" fill="#888" font-size="11">Bypass = shunt HF noise to GND. Decoupling = local charge for transients. Same part, two jobs.</text></svg></div>$vsq$ as box) n
 where question like $q$%Bypass Capacitor（旁路電容）和%$q$;

-- q23：差分對走線 對 vs 錯
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="244" viewBox="0 0 520 244" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="244" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Differential pair routing</text><text x="130" y="40" fill="#00ff88" font-size="12" font-weight="bold" text-anchor="middle">(C) correct</text><text x="390" y="40" fill="#ff6b6b" font-size="12" font-weight="bold" text-anchor="middle">(A)(B)(D) wrong</text><line x1="260" y1="32" x2="260" y2="176" stroke="#334155" stroke-width="1"/><rect x="20" y="140" width="220" height="16" fill="#1f2937"/><text x="130" y="152" fill="#94a3b8" font-size="11" text-anchor="middle">solid reference plane</text><polyline points="24,68 96,68 128,96 236,96" fill="none" stroke="#00d4ff" stroke-width="2"/><polyline points="24,82 96,82 128,110 236,110" fill="none" stroke="#00d4ff" stroke-width="2"/><text x="24" y="60" fill="#00ff88" font-size="11">equal length, constant gap, one layer</text><rect x="280" y="140" width="86" height="16" fill="#1f2937"/><rect x="394" y="140" width="86" height="16" fill="#1f2937"/><text x="380" y="170" fill="#ff6b6b" font-size="11" text-anchor="middle">plane split breaks the return</text><polyline points="284,68 344,68" fill="none" stroke="#00d4ff" stroke-width="2"/><circle cx="344" cy="68" r="4" fill="none" stroke="#ff6b6b" stroke-width="1.6"/><polyline points="344,68 380,68 380,96 496,96" fill="none" stroke="#00d4ff" stroke-width="2" stroke-dasharray="5"/><polyline points="284,82 430,82 430,120 496,120" fill="none" stroke="#00d4ff" stroke-width="2"/><text x="284" y="60" fill="#ff6b6b" font-size="11">via to another layer, 90 deg turns</text><text x="10" y="198" fill="#c8d4ee" font-size="11">Equal length keeps skew under 5mil. Constant gap keeps Zdiff constant.</text><text x="10" y="218" fill="#888" font-size="11">Splitting layers changes impedance and coupling; a 90 deg corner and a plane split both hurt.</text><text x="10" y="238" fill="#888" font-size="11">Dashed = the half that jumped layers, so the two halves no longer match.</text></svg></div>$vsq$ as box) n
 where question like $q$%PCB 設計中，高速差分對走線%$q$;

-- q24：六參數 + FOM 權衡曲線
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="244" viewBox="0 0 520 244" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="244" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">MOSFET selection: six parameters and FOM</text><text x="16" y="52" fill="#00d4ff" font-size="11">V(BR)DSS</text><text x="104" y="52" fill="#c8d4ee" font-size="11">pick &gt;= 1.2 x Vmax</text><text x="16" y="76" fill="#00d4ff" font-size="11">RDS(on)</text><text x="104" y="76" fill="#c8d4ee" font-size="11">conduction loss I^2 R</text><text x="16" y="100" fill="#00d4ff" font-size="11">Qg</text><text x="104" y="100" fill="#c8d4ee" font-size="11">gate charge -> switching</text><text x="16" y="124" fill="#00d4ff" font-size="11">VGS(th)</text><text x="104" y="124" fill="#c8d4ee" font-size="11">turn-on threshold</text><text x="16" y="148" fill="#00d4ff" font-size="11">ID(max)</text><text x="104" y="148" fill="#c8d4ee" font-size="11">continuous drain current</text><text x="16" y="172" fill="#00d4ff" font-size="11">SOA</text><text x="104" y="172" fill="#c8d4ee" font-size="11">safe operating area</text><line x1="330" y1="66" x2="330" y2="190" stroke="#888" stroke-width="1.4"/><line x1="330" y1="190" x2="500" y2="190" stroke="#888" stroke-width="1.4"/><polyline points="360.6,81.7 364.0,92.5 367.4,101.4 370.8,108.8 374.2,115.0 377.6,120.4 381.0,125.0 384.4,129.1 387.8,132.6 391.2,135.8 394.6,138.7 398.0,141.3 401.4,143.6 404.8,145.7 408.2,147.6 411.6,149.4 415.0,151.0 418.4,152.5 421.8,153.9 425.2,155.2 428.6,156.4 432.0,157.5 435.4,158.5 438.8,159.5 442.2,160.5 445.6,161.3 449.0,162.1 452.4,162.9 455.8,163.6 459.2,164.3 462.6,165.0 466.0,165.6 469.4,166.2 472.8,166.8 476.2,167.3 479.6,167.8 483.0,168.3 486.4,168.8 489.8,169.3 493.2,169.7 496.6,170.1 500.0,170.5" fill="none" stroke="#ff6b6b" stroke-width="1.8"/><polyline points="360.6,146.7 364.0,151.0 367.4,154.5 370.8,157.5 374.2,160.0 377.6,162.1 381.0,164.0 384.4,165.6 387.8,167.1 391.2,168.3 394.6,169.5 398.0,170.5 401.4,171.4 404.8,172.3 408.2,173.0 411.6,173.8 415.0,174.4 418.4,175.0 421.8,175.6 425.2,176.1 428.6,176.6 432.0,177.0 435.4,177.4 438.8,177.8 442.2,178.2 445.6,178.5 449.0,178.9 452.4,179.2 455.8,179.5 459.2,179.7 462.6,180.0 466.0,180.3 469.4,180.5 472.8,180.7 476.2,180.9 479.6,181.1 483.0,181.3 486.4,181.5 489.8,181.7 493.2,181.9 496.6,182.0 500.0,182.2" fill="none" stroke="#00ff88" stroke-width="1.8"/><text x="330" y="52" fill="#888" font-size="11" text-anchor="middle">RDS(on)</text><text x="504" y="194" fill="#888" font-size="11">Qg</text><text x="404" y="88" fill="#ff6b6b" font-size="11">worse FOM</text><text x="336" y="182" fill="#00ff88" font-size="11">better FOM</text><text x="10" y="212" fill="#c8d4ee" font-size="11">FOM = RDS(on) x Qg, lower is better - it balances conduction against switching loss.</text><text x="10" y="234" fill="#888" font-size="11">Low frequency, high current: chase RDS(on). High frequency: chase Qg.</text></svg></div>$vsq$ as box) n
 where question like $q$%MOSFET 選型時需要關注%$q$;

-- q25：寄生 SCR 等效電路
update public.interview_questions set
  answer = case when answer is not null and answer not like '%<svg%' then n.box || answer else answer end,
  answer_en = case when answer_en is not null and answer_en not like '%<svg%' then n.box || answer_en else answer_en end,
  answer_ja = case when answer_ja is not null and answer_ja not like '%<svg%' then n.box || answer_ja else answer_ja end,
  answer_ko = case when answer_ko is not null and answer_ko not like '%<svg%' then n.box || answer_ko else answer_ko end
  from (select $vsq$<div class="exam-diagram-box"><svg width="520" height="252" viewBox="0 0 520 252" xmlns="http://www.w3.org/2000/svg"><rect width="520" height="252" fill="#0a0a1a"/><text x="260" y="18" fill="#00d4ff" font-size="13" font-weight="bold" text-anchor="middle">Latch-up: the parasitic PNPN (SCR) in CMOS</text><path d="M120,58 V196" fill="none" stroke="#ff6b6b" stroke-width="8" stroke-opacity="0.25" stroke-linecap="round"/><line x1="120" y1="44" x2="120" y2="58" stroke="#ff6b6b" stroke-width="1.6"/><text x="128" y="54" fill="#ff6b6b" font-size="11">VDD</text><rect x="102" y="58" width="36" height="20" fill="none" stroke="#ffc107" stroke-width="1.6"/><text x="96" y="72" fill="#ffc107" font-size="11" text-anchor="end">Rwell</text><rect x="102" y="86" width="36" height="26" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="120" y="103" fill="#00d4ff" font-size="11" text-anchor="middle">PNP</text><rect x="102" y="130" width="36" height="26" rx="3" fill="none" stroke="#00d4ff" stroke-width="1.6"/><text x="120" y="147" fill="#00d4ff" font-size="11" text-anchor="middle">NPN</text><rect x="102" y="164" width="36" height="20" fill="none" stroke="#ffc107" stroke-width="1.6"/><text x="96" y="178" fill="#ffc107" font-size="11" text-anchor="end">Rsub</text><line x1="120" y1="184" x2="120" y2="196" stroke="#888" stroke-width="1.6"/><line x1="102" y1="196" x2="138" y2="196" stroke="#888" stroke-width="1.6"/><line x1="108" y1="201" x2="132" y2="201" stroke="#888" stroke-width="1.4"/><line x1="114" y1="206" x2="126" y2="206" stroke="#888" stroke-width="1.2"/><polyline points="138,106 160,106 160,136 138,136" fill="none" stroke="#00ff88" stroke-width="1.4"/><polyline points="102,136 84,136 84,92 102,92" fill="none" stroke="#00ff88" stroke-width="1.4"/><text x="166" y="100" fill="#00ff88" font-size="11">regenerative</text><line x1="230" y1="121" x2="176" y2="121" stroke="#ff6b6b" stroke-width="1.6"/><polygon points="176,117 176,125 166,121" fill="#ff6b6b"/><text x="234" y="125" fill="#ff6b6b" font-size="11">IO above VDD or below GND</text><text x="270" y="60" fill="#ff6b6b" font-size="11">Triggers</text><text x="270" y="78" fill="#c8d4ee" font-size="11">IO overshoot beyond a diode drop</text><text x="270" y="96" fill="#c8d4ee" font-size="11">large injected current (ESD)</text><text x="270" y="150" fill="#00ff88" font-size="11">Prevention</text><text x="270" y="168" fill="#c8d4ee" font-size="11">guard rings: P+ to VDD, N+ to GND</text><text x="270" y="186" fill="#c8d4ee" font-size="11">VDD before IO, series R on IO</text><text x="270" y="204" fill="#c8d4ee" font-size="11">clamp diodes, dense well taps</text><text x="10" y="228" fill="#ff6b6b" font-size="11">Once latched, VDD-to-GND stays low impedance (red path) - only a power cycle clears it.</text><text x="10" y="246" fill="#888" font-size="11">Bad power sequencing and high temperature both lower the trigger threshold.</text></svg></div>$vsq$ as box) n
 where question like $q$%什麼是 Latch-up%$q$;

-- 驗收：七列的 zh / en 都要 t
select left(question, 22) as q,
       answer like '%<svg%' as zh, answer_en like '%<svg%' as en,
       answer_ja like '%<svg%' as ja, answer_ko like '%<svg%' as ko
  from public.interview_questions
 where question like $q$%tr (上升時間) FAIL%$q$
    or question like $q$%什麼是 ESD%$q$
    or question like $q$%Bypass Capacitor（旁路電容）和%$q$
    or question like $q$%PCB 設計中，高速差分對走線%$q$
    or question like $q$%MOSFET 選型時需要關注%$q$
    or question like $q$%什麼是 Latch-up%$q$;
